import React, { useEffect, useState } from 'react';
import { LoadingPlaceholder } from '@grafana/ui';
import { getSupportedDataSources, type SupportedDataSourceSettings } from '../../api/data-sources';
import DataSourceConnectField from './DataSourceConnectField';
import DataSourceSelectField, { type DataSourceSelectFieldProps } from './DataSourceSelectField';

interface DataSourceEditorProps extends Omit<DataSourceSelectFieldProps, 'dataSources'> {
}

const DataSourceEditor: React.FC<DataSourceEditorProps> = (props) => {
  const [dataSources, setDataSources] = useState<SupportedDataSourceSettings[] | undefined>(undefined);

  useEffect(() => {
    getSupportedDataSources().then(setDataSources);
  }, []);

  return !dataSources ? (
    <LoadingPlaceholder text="" />
  ) : !dataSources.length ? (
    <DataSourceConnectField pluginName={props.pluginName} />
  ) : (
    <DataSourceSelectField dataSources={dataSources} {...props} />
  );
};

export default DataSourceEditor;

export type { DataSourceChangeHandler } from './DataSourceSelectField';
