import React, { useCallback, useState } from 'react';
import { Button, Container, TextLink } from '@grafana/ui';
import { TCXPluginMeta, TCXPluginSettings } from '../types';
import DataSourceEditor, { type DataSourceChangeHandler } from '../components/DataSourcEditor';
import { updatePlugin } from '../api/plugin';
import { createDashboardsFolder, getDashboardsFolder } from '../api/folders';
import { createDashboard, deleteDashboard, getDashboards } from '../api/dashboards';
import { prepareNewDashboards } from '../dashboards/prepare-new-dashboards';
import { DASHBOARDS_FOLDER_PAGE, mainPage } from '../routes';
import { PluginPage } from '@grafana/runtime';
import { Trans } from 'react-i18next';
import { type ActionStep, ActionStepsRunner } from '../components/ActionStepsRunner';

// ConfigurationPage handles data source selection and creates monitoring dashboards with the selected data source.
// Publishing is visualized with a list of steps.
//
// Free tier grafana fails on simultaneous requests, so
// 1. we run all requests consequentially;
// 2. we display the process with the ability to retry failed steps;
//
// if no errors on the run - user will be redirected to the main page which shows all published dashboards
// if there were errors - user will see step logs with retry buttons
// after everything retried to success, text "All dashboards published" will appear, no redirect will be performed.
const ConfigurationPage: React.FC<TCXPluginMeta> = (props) => {
  const { jsonData, name } = props;
  const [dataSource, setDataSource] = useState(jsonData?.dataSource);
  const [publishSteps, setPublishSteps] = useState<ActionStep[] | null>(null);
  const [publishKey, setPublishKey] = useState<string | null>(null);

  const onDataSourceChange = useCallback<DataSourceChangeHandler>((value, status) => {
    setDataSource(status === 'OK' ? value : undefined);
  }, []);

  const publishDashboards = useCallback(() => {
    if (!dataSource) {
      return;
    }
    const settings: TCXPluginSettings = { dataSource };
    const steps: ActionStep[] = [
      {
        title: 'Saving selected data source',
        critical: true,
        action: () => updatePlugin(props.id, { ...props, jsonData: settings }),
      },
      {
        title: 'Preparing publishing steps',
        critical: true,
        action: async () => {
          const folder = (await getDashboardsFolder()) ?? (await createDashboardsFolder());
          const oldDashboards = await getDashboards();
          const newDashboards = prepareNewDashboards(settings);

          setPublishSteps(
            steps.concat([
              ...oldDashboards.map((dashboard) => ({
                title: 'Deleting',
                titleParam: dashboard.title,
                action: () => deleteDashboard(dashboard),
              })),
              ...newDashboards.map((dashboard) => ({
                title: 'Publishing',
                titleParam: dashboard.title,
                action: () => createDashboard(folder, dashboard),
              })),
            ])
          );
        },
      },
    ];

    setPublishSteps(steps);
    setPublishKey(new Date().getTime().toString());
  }, [props, dataSource]);

  const onPublishComplete = useCallback((withRetries: boolean) => {
    if (!withRetries) {
      // redirect to the main page if publish was flawless
      location.href = mainPage(props.id);
    }
  }, [props.id]);

  return (
    <PluginPage renderTitle={() => <h1><Trans>3CX Plugin Configuration</Trans></h1>}>
      <div><Trans>Configure your 3CX phone system monitoring by completing these steps</Trans>:</div>
      <Container padding={'md'}>
        <ol>
          <li><Trans>Connect and choose a data source bound to your CDR data storage</Trans></li>
          <li><Trans>Click &#34;Publish Dashboards&#34; to generate monitoring dashboards</Trans></li>
        </ol>
      </Container>
      <p>
        <strong><Trans>Note</Trans>:</strong> <Trans>publishing will replace any existing 3CX dashboards.</Trans>
        <br />
        <Trans>
          The new dashboards will be available in <TextLink href={DASHBOARDS_FOLDER_PAGE}>3CX dashboards folder</TextLink>.
        </Trans>
      </p>

      <DataSourceEditor value={dataSource} onChange={onDataSourceChange} pluginName={name} />
      <Button disabled={!dataSource} onClick={publishDashboards}>
        <Trans>Publish dashboards</Trans>
      </Button>
      <br />
      <br />
      {publishSteps && (
        <ActionStepsRunner
          key={publishKey}
          steps={publishSteps}
          complete={onPublishComplete}
          completeMessage="All dashboards published"
        />
      )}
    </PluginPage>
  );
};

export default ConfigurationPage;
