import React, { useCallback, useMemo, useState } from 'react';
import { useReturnToPrevious } from '@grafana/runtime';
import { DATASOURCE_TYPE_LABEL, SUPPORTED_DATASOURCE_TYPES, SupportedDataSourceType } from '../../constants';
import { Button, Field, Combobox, Stack, type ComboboxOption } from '@grafana/ui';
import { createDataSource } from '../../api/data-sources';
import { dataSourceEditPage } from '../../routes';
import { Trans, useTranslation } from 'react-i18next';

interface ConnectDataSourceFieldProps {
  pluginName: string
}

// Component allows going straight to datasource setup page for chosen datasource type with easy way to return back
const DataSourceConnectField: React.FC<ConnectDataSourceFieldProps> = ({ pluginName }) => {
  const { t } = useTranslation();
  const setReturnToPrevious = useReturnToPrevious();
  const [type, setType] = useState<SupportedDataSourceType | undefined>(undefined);

  const typeOptions = useMemo(
    () => SUPPORTED_DATASOURCE_TYPES.map((value) => ({ label: DATASOURCE_TYPE_LABEL[value], value })),
    []
  );

  const onTypeSelect = useCallback((option: ComboboxOption<SupportedDataSourceType>) => {
    setType(option.value);
  }, []);

  const onConnectClick = useCallback(async () => {
    if (!type) {
      return;
    }
    createDataSource(type)
      .then((dataSource) => {
        setReturnToPrevious(pluginName);
        location.href = dataSourceEditPage(dataSource);
      })
      .catch(() => {
        // the request error is shown by grafana's alert toast
      });
  }, [type, setReturnToPrevious, pluginName]);

  return (
    <Field label={t('Connect Data Source')}>
      <Stack direction="row">
        <Combobox
          width={50}
          options={typeOptions}
          value={type}
          onChange={onTypeSelect}
          placeholder={t('Choose data source type')}
        />
        <Button type="button" disabled={!type} onClick={onConnectClick}>
          <Trans>Connect</Trans>
        </Button>
      </Stack>
    </Field>
  );
};

export default DataSourceConnectField;
