import { getBackendSrv } from '@grafana/runtime';
import { SHOW_ERROR_ALERT, DASHBOARDS_FOLDER_UID, DASHBOARDS_FOLDER_TITLE, HIDE_ERROR_ALERT } from './constants';

export interface FolderMeta {
  uid: string;
  title: string;
}

/** returns folder for 3CX dashboards */
export function getDashboardsFolder(): Promise<FolderMeta | null> {
  return getBackendSrv()
    .get<FolderMeta>('/api/folders/' + DASHBOARDS_FOLDER_UID, undefined, undefined, HIDE_ERROR_ALERT)
    .catch(() => null)
}

/** creates folder for 3CX dashboards */
export function createDashboardsFolder(): Promise<FolderMeta> {
  return getBackendSrv().post<FolderMeta>(
    '/api/folders',
    { uid: DASHBOARDS_FOLDER_UID, title: DASHBOARDS_FOLDER_TITLE },
    SHOW_ERROR_ALERT
  );
}
