import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useReturnToPrevious } from '@grafana/runtime';
import { getDataSourceHealth, DataSourceHealthStatus, SupportedDataSourceSettings } from '../../api/data-sources';
import { Combobox, Field, Icon, LoadingPlaceholder, Stack, TextLink, type ComboboxOption } from '@grafana/ui';
import { DATASOURCE_NAME_PREFIX } from '../../api/constants';
import { dataSourceEditPage } from '../../routes';
import { DataSourceInfo } from '../../types';
import { DATASOURCE_TYPE_LABEL } from '../../constants';
import { useTranslation } from 'react-i18next';

export type DataSourceChangeHandler = (value?: DataSourceInfo, status?: DataSourceHealthStatus) => void;

export interface DataSourceSelectFieldProps {
  pluginName: string;
  dataSources: SupportedDataSourceSettings[];
  value: DataSourceInfo | undefined;
  onChange: DataSourceChangeHandler;
}

// Component allows choosing datasource from the list of available,
// checks health for the chosen datasource and sets a quick link for unhealthy datasource setup check
const DataSourceSelectField: React.FC<DataSourceSelectFieldProps> = ({ dataSources, value, onChange, pluginName }) => {
  const { t } = useTranslation();
  const setReturnToPrevious = useReturnToPrevious();
  const beforeGoingAway = useCallback(() => setReturnToPrevious(pluginName), [setReturnToPrevious, pluginName]);

  const [dataSource, setDataSource] = useState<SupportedDataSourceSettings | undefined>(undefined);
  const [dataSourceHealth, setDataSourceHealth] = React.useState<DataSourceHealthStatus | 'Pending' | undefined>(undefined);

  const dataSourceOptions = useMemo(
    () => dataSources.map((ds) => ({ label: ds.name, value: ds.uid, group: DATASOURCE_TYPE_LABEL[ds.type] })),
    [dataSources]
  );

  const onDataSourceSelect = useCallback(
    (option: ComboboxOption) => {
      setDataSource(dataSources?.find((ds) => ds.uid === option.value));
    },
    [dataSources]
  );

  // sync outer and inner value
  useEffect(() => {
    setDataSource(
      value
        ? dataSources.find((ds) => ds.uid === value.uid)
        : dataSources.find((ds) => ds.name.startsWith(DATASOURCE_NAME_PREFIX))
    );
  }, [value, dataSources]);

  // change handler, fired on start also to deliver status
  useEffect(() => {
    const healthRequest = dataSource ? getDataSourceHealth(dataSource.uid) : Promise.resolve(undefined);

    setDataSourceHealth('Pending');
    healthRequest.then((healthStatus) => {
      setDataSourceHealth(healthStatus);
      onChange(dataSource && { name: dataSource.name, type: dataSource.type, uid: dataSource.uid }, healthStatus);
    });
  }, [dataSource, onChange]);

  return (
    <Field label={t("Data Source")}>
      <Stack direction="row" gap={2} alignItems="center">
        <Combobox
          width={50}
          options={dataSourceOptions}
          value={dataSource?.uid}
          onChange={onDataSourceSelect}
          placeholder={t('Choose data source')}
        />
        {dataSourceHealth === 'OK' && <Icon name="check-circle" title={t('Data source is connected and healthy')} color="green" />}
        {dataSourceHealth === 'Pending' && (
          <LoadingPlaceholder text="" style={{ marginBottom: 2 }} title={t('Checking data source health')} />
        )}
        {dataSource && dataSourceHealth === 'Unhealthy' && (
          <>
            <Icon name="exclamation-triangle" title={t('Data source is not connected')} color="orange" />
            <TextLink href={dataSourceEditPage(dataSource)} onClick={beforeGoingAway}>
              {t('Check data source')}
            </TextLink>
          </>
        )}
      </Stack>
    </Field>
  );
};

export default DataSourceSelectField;
