import React, { useEffect, useMemo } from 'react';
import { Stack } from '@grafana/ui';
import { ActionStep, ActionStepView } from './ActionStepView';

interface ActionStepsRunnerProps {
  steps: ActionStep[];
  complete: (hadErrors: boolean) => void;
  completeMessage?: string;
}

// Component automatically runs the next available step from the list,
// shows execution progress and reports back step status.
export const ActionStepsRunner: React.FC<ActionStepsRunnerProps> = ({ steps, complete, completeMessage }) => {
  // wrapping steps instance into a state object to be able to trigger rerender without losing state in step action
  const [state, setState] = React.useState<{ steps: ActionStep[] }>({ steps: [] });
  const [finishedStep, setFinishedStep] = React.useState<ActionStep | null>(null);
  const notInProgress = useMemo(() => !state.steps.some(step => step.inProgress), [state]);
  const allDone = useMemo(() => state.steps.every(step => step.done), [state]);

  function runNextAvailableStep() {
    if (steps.some((s) => s.inProgress)) {
      return;
    }
    const step = steps.find((s) => !s.done && !s.error);
    if (!step) {
      return;
    }
    const action = step.action;

    // redefining for retry
    // this method operates an outdated state ref, but its content is correct
    step.action = async () => {
      try {
        step.inProgress = true;
        setState({ ...state });

        await action();

        step.done = true;
        step.inProgress = false;
        setState({ ...state });
        setFinishedStep(step);
      } catch {
        step.error = true;
        step.inProgress = false;
        setState({ ...state });
        if(!step.critical) {
          setFinishedStep(step);
        }
      }
    };
    state.steps.push(step);
    setState({ ...state });
    step.action();
  }

  // callback runs on component mount and on each step finish
  useEffect(() => {
    runNextAvailableStep();
    if (finishedStep && state.steps.every((step) => step.done)) {
      complete(state.steps.some((step) => step.error));
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [finishedStep]);

  return (
    <Stack direction="column" gap={1}>
      {state.steps.map(step => <ActionStepView key={step.title} step={step} canRetry={notInProgress} />)}
      {completeMessage && allDone && <ActionStepView step={{ title: completeMessage, action: Promise.resolve, done: true, critical: true }} />}
    </Stack>
  );
};
