import { getBackendSrv } from '@grafana/runtime';
import type { Dashboard } from '@grafana/schema';
import type { FolderMeta } from './folders';
import { SHOW_ERROR_ALERT, DASHBOARD_TAG } from './constants';


export interface DashboardMeta {
  uid: string;
  title: string;
}
/** returns a list of existing 3CX dashboards */
export function getDashboards(): Promise<DashboardMeta[]> {
  return getBackendSrv()
    .get<DashboardMeta[]>('/api/search', { type: 'dash-db', tag: [DASHBOARD_TAG] }, undefined, SHOW_ERROR_ALERT)
    .catch(() => []);
}

/** puts a new 3CX dashboard into the given folder */
export function createDashboard(folder: FolderMeta, dashboard: Dashboard): Promise<DashboardMeta> {
  return getBackendSrv().post<DashboardMeta>(
    '/api/dashboards/db',
    { folderUid: folder.uid, dashboard: { ...dashboard, tags: [DASHBOARD_TAG] } },
    SHOW_ERROR_ALERT
  );
}

/** deletes given dashboard */
export function deleteDashboard(dashboard: DashboardMeta): Promise<void> {
  return getBackendSrv().delete('/api/dashboards/uid/' + dashboard.uid, undefined, SHOW_ERROR_ALERT);
}
