import type { TCXPluginMeta } from '../types';
import { getBackendSrv } from '@grafana/runtime';
import { SHOW_ERROR_ALERT } from './constants';


export function updatePlugin(pluginId: string, data: Partial<TCXPluginMeta>) {
  return getBackendSrv().post<TCXPluginMeta>(`/api/plugins/${pluginId}/settings`, data, SHOW_ERROR_ALERT);
}
