import type { Dashboard as DashboardSpec } from '@grafana/schema';
import { TCXPluginSettings } from '../types';
import { DASHBOARDS } from './data';

// taking prepared for import dashboards and replacing inputs with actual values from settings
export function prepareNewDashboards(settings: TCXPluginSettings): DashboardSpec[] {
  return DASHBOARDS[settings.dataSource.type].map((dashboard) => {
    const { __inputs, __elements, __requires, uid, version, schemaVersion, ...spec } = dashboard;

    return replaceInputVariables({ ...spec, editable: false } as DashboardSpec, settings);
  });
}

function replaceInputVariables<T>(source: T, settings: TCXPluginSettings): T {
  if (!source || typeof source !== 'object') {
    return source;
  }
  if (Array.isArray(source)) {
    return source.map((element) => replaceInputVariables(element, settings)) as T;
  }
  return Object.fromEntries(
    Object.entries(source).map(([key, value]) =>
      key === 'datasource' && value && typeof value === 'object' && value.type === settings.dataSource.type
        // Replacing input variable reference with actual data source uid
        ? [key, { ...value, uid: settings.dataSource.uid }]
        // Other replacement cases can be here in the future
        : [key, replaceInputVariables(value, settings)]
    )
  ) as T;
}
