import React, { CSSProperties } from 'react';
import { Button, Icon, Stack } from '@grafana/ui';
import { Trans } from 'react-i18next';

export interface ActionStep {
  title: string;
  titleParam?: string;
  action: () => Promise<unknown>;
  inProgress?: boolean;
  done?: boolean;
  error?: boolean;
  critical?: boolean;
}

interface ActionStepViewProps {
  step: ActionStep;
  canRetry?: boolean;
}

export const ActionStepView: React.FC<ActionStepViewProps> = ({ step, canRetry }) => {
  if (step.done ? !step.critical : !step.error && !step.inProgress) {
    return null;
  }

  // reserve button space to avoid layout shift
  const buttonStyle: CSSProperties = !step.done && step.error ? {} : { visibility: 'hidden' };

    return (
      <Stack direction="row" gap={1} alignItems="center">
        {
          (step.inProgress && <Icon name="spinner" color="grey" />) ||
          (step.done && <Icon name="check-circle" color="green" />) ||
          (step.error && <Icon name="exclamation-triangle" color="orange" />)
        }
        <Trans>{step.title}</Trans> {step.titleParam}
        <Button fill="text" size="sm" onClick={step.action} disabled={!canRetry} style={buttonStyle}>
          <Trans>retry</Trans>
        </Button>
      </Stack>
    );
};
